use fleetring::{StableHasher, Xxh3};

/// XXH3-64 reference values as `(input length, seed, hash)`; see [`pattern`] for the input.
///
/// Generated by `scripts/xxh3_vectors.py` with python-xxhash 4.0.2 (C xxHash 0.8.3). The
/// lengths cover every XXH3 code path: 0, 1–3, 4–8, 9–16, 17–128, 129–240, and above 240.
const XXH3_VECTORS: &[(usize, u64, u64)] = &[
    (0, 0x0000000000000000, 0x2d06800538d394c2),
    (0, 0x0000000000000001, 0x4dc5b0cc826f6703),
    (0, 0x9e3779b97f4a7c15, 0x602b0e2cd6662c8b),
    (1, 0x0000000000000000, 0x4c5cca45d0f4811f),
    (1, 0x0000000000000001, 0x0a187bf012eca100),
    (1, 0x9e3779b97f4a7c15, 0x2f3acd3805f81de3),
    (3, 0x0000000000000000, 0x15f7093b173d005c),
    (3, 0x0000000000000001, 0x2d2f08ad1dcf5855),
    (3, 0x9e3779b97f4a7c15, 0x079dd5d54d89480a),
    (4, 0x0000000000000000, 0xdca012f95811b6b9),
    (4, 0x0000000000000001, 0x147ba1078a952951),
    (4, 0x9e3779b97f4a7c15, 0x1a246e2efb9c9b2e),
    (8, 0x0000000000000000, 0xdec6a9a43575982e),
    (8, 0x0000000000000001, 0x93db64e0c78addf0),
    (8, 0x9e3779b97f4a7c15, 0x19ef7d3919108aff),
    (9, 0x0000000000000000, 0xcbe393399f17ffbd),
    (9, 0x0000000000000001, 0x9b4ac94407ef94f7),
    (9, 0x9e3779b97f4a7c15, 0x9c98d3e24dc54d34),
    (16, 0x0000000000000000, 0x7e484c18d74895d0),
    (16, 0x0000000000000001, 0x5eb10bd46ebeb101),
    (16, 0x9e3779b97f4a7c15, 0xa106510078b0a252),
    (17, 0x0000000000000000, 0x208bde5ee2bed407),
    (17, 0x0000000000000001, 0x40ee90e37ff57a2c),
    (17, 0x9e3779b97f4a7c15, 0x0b2caf8bf9648eff),
    (128, 0x0000000000000000, 0xf92b70eaa21a6288),
    (128, 0x0000000000000001, 0x6673c6814e935b97),
    (128, 0x9e3779b97f4a7c15, 0x95425530beb89fe8),
    (129, 0x0000000000000000, 0xf8f76713f2bb60fa),
    (129, 0x0000000000000001, 0x9638166292586e74),
    (129, 0x9e3779b97f4a7c15, 0x29fa850b97ed9666),
    (240, 0x0000000000000000, 0xccc7375172c41f03),
    (240, 0x0000000000000001, 0x8b1fdbbe81e5919e),
    (240, 0x9e3779b97f4a7c15, 0x2d882e7899ff64cc),
    (241, 0x0000000000000000, 0x0b3b630948ce4a00),
    (241, 0x0000000000000001, 0x74435d0ed97c22f9),
    (241, 0x9e3779b97f4a7c15, 0x422e82e8913e49e0),
    (1024, 0x0000000000000000, 0x23bc880ebf0d29c6),
    (1024, 0x0000000000000001, 0xb5bf4ccc6942b02d),
    (1024, 0x9e3779b97f4a7c15, 0x7e249adc60e1f9b4),
];

/// The reference input of `len` bytes: byte `i` is `(31 * i + 7) mod 256`.
fn pattern(len: usize) -> Vec<u8> {
    std::iter::successors(Some(7u8), |byte| Some(byte.wrapping_add(31)))
        .take(len)
        .collect()
}

#[test]
fn xxh3_matches_the_c_reference() {
    for &(len, seed, want) in XXH3_VECTORS {
        let got = Xxh3.hash(&pattern(len), seed);
        assert_eq!(got, want, "XXH3-64 of {len} bytes under seed {seed:#018x}");
    }
}

#[test]
fn xxh3_reports_its_algorithm() {
    assert_eq!(Xxh3.algorithm(), "xxh3-64");
}

#[test]
fn references_and_boxes_forward_to_the_hasher() {
    fn hash_with<H: StableHasher>(hasher: H) -> (u64, &'static str) {
        (hasher.hash(b"agent:sam-researcher", 42), hasher.algorithm())
    }

    let want = hash_with(Xxh3);
    let by_ref: &Xxh3 = &Xxh3;
    let borrowed: &dyn StableHasher = &Xxh3;
    let boxed: Box<dyn StableHasher> = Box::new(Xxh3);
    assert_eq!(hash_with(by_ref), want);
    assert_eq!(hash_with(borrowed), want);
    assert_eq!(hash_with(&boxed), want);
    assert_eq!(hash_with(boxed), want);
}

#[cfg(feature = "test-util")]
#[test]
fn table_hasher_overrides_listed_inputs_only() {
    use fleetring::test_util::TableHasher;

    let hasher = TableHasher::new().with("node-a", 100).with([0u8; 16], 5);
    assert_eq!(hasher.hash(b"node-a", 0), 100);
    assert_eq!(
        hasher.hash(b"node-a", 7),
        100,
        "listed inputs ignore the seed"
    );
    assert_eq!(hasher.hash(&[0u8; 16], 3), 5);
    assert_eq!(hasher.hash(b"node-b", 7), Xxh3.hash(b"node-b", 7));
}
